import React, { useState } from 'react';
import { Globe, MapPin, Users, ChevronDown, ChevronUp, Shield, Scroll, AlertTriangle } from 'lucide-react';

const WorldInfoPanel = ({ worldBlueprint, currentLocation, embedded = false }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  if (!worldBlueprint) {
    return null;
  }

  // When embedded (e.g. inside a Sheet), skip the inline header toggle and
  // always render the body content. Caller owns the chrome.
  const showBody = embedded || isExpanded;

  const worldCore = worldBlueprint.world_core || {};
  const startingRegion = worldBlueprint.starting_region || {};
  const startingTown = worldBlueprint.starting_town || {};
  const pois = worldBlueprint.points_of_interest || [];
  const npcs = worldBlueprint.key_npcs || [];
  const setting = worldBlueprint.setting || {};
  // Factions can be on worldBlueprint.factions (legacy) OR worldBlueprint.setting.factions (V2)
  const factions = setting.factions?.length ? setting.factions : (worldBlueprint.factions || []);
  const recentEvents = setting.recent_events || [];
  const era = setting.era;
  const currentTension = setting.current_tension;

  return (
    <div className={embedded ? '' : 'bg-gray-800 rounded-lg shadow-lg overflow-hidden border border-gray-700'}>
      {/* Header - hidden when embedded inside a Sheet */}
      {!embedded && (
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="w-full flex items-center justify-between p-4 hover:bg-gray-750 transition-colors"
        >
          <div className="flex items-center gap-3">
            <Globe className="text-blue-400" size={24} />
            <div className="text-left">
              <h3 className="text-white font-bold text-lg">
                {worldCore.name || 'Unknown Realm'}
              </h3>
              <p className="text-gray-400 text-sm">
                {currentLocation || startingTown.name || 'Exploring...'}
              </p>
            </div>
          </div>
          {isExpanded ? (
            <ChevronUp className="text-gray-400" size={20} />
          ) : (
            <ChevronDown className="text-gray-400" size={20} />
          )}
        </button>
      )}

      {/* Expandable content */}
      {showBody && (
        <div className={embedded ? 'space-y-4' : 'p-4 pt-0 space-y-4 border-t border-gray-700'}>
          {/* World Info */}
          <div>
            <p className="text-gray-300 text-sm leading-relaxed">
              {worldCore.summary || 'A realm of mystery and adventure.'}
            </p>
            {worldCore.tone && (
              <p className="text-gray-500 text-xs mt-1 italic">
                Tone: {worldCore.tone}
              </p>
            )}
          </div>

          {/* Era */}
          {era && (
            <div>
              <div className="flex items-center gap-2 mb-1">
                <Scroll className="text-amber-400" size={16} />
                <h4 className="text-amber-400 font-semibold text-sm">The Age</h4>
              </div>
              <p className="text-gray-300 text-sm leading-relaxed ml-6" data-testid="world-era">{era}</p>
            </div>
          )}

          {/* Current Tension */}
          {currentTension && (
            <div>
              <div className="flex items-center gap-2 mb-1">
                <AlertTriangle className="text-orange-400" size={16} />
                <h4 className="text-orange-400 font-semibold text-sm">What the Streets Feel Like</h4>
              </div>
              <p className="text-gray-300 text-sm leading-relaxed italic ml-6" data-testid="world-tension">{currentTension}</p>
            </div>
          )}

          {/* Region */}
          {startingRegion.name && (
            <div>
              <div className="flex items-center gap-2 mb-2">
                <MapPin className="text-green-400" size={16} />
                <h4 className="text-green-400 font-semibold text-sm">
                  Region: {startingRegion.name}
                </h4>
              </div>
              <p className="text-gray-400 text-sm ml-6">
                {startingRegion.summary || startingRegion.description || 'A mysterious region.'}
              </p>
            </div>
          )}

          {/* Points of Interest */}
          {pois.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <MapPin className="text-yellow-400" size={16} />
                <h4 className="text-yellow-400 font-semibold text-sm">
                  Points of Interest
                </h4>
              </div>
              <div className="ml-6 space-y-3">
                {pois.slice(0, 5).map((poi, idx) => (
                  <div key={idx} className="text-sm leading-relaxed">
                    <span className="text-white font-semibold">{poi.name}:</span>
                    <span className="text-gray-300 ml-1">
                      {poi.summary || poi.description || 'A notable location.'}
                    </span>
                  </div>
                ))}
                {pois.length > 5 && (
                  <p className="text-gray-500 text-xs italic">
                    ...and {pois.length - 5} more locations to discover
                  </p>
                )}
              </div>
            </div>
          )}

          {/* Key NPCs */}
          {npcs.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Users className="text-purple-400" size={16} />
                <h4 className="text-purple-400 font-semibold text-sm">
                  Notable Figures
                </h4>
              </div>
              <div className="space-y-1 ml-6">
                {npcs.slice(0, 4).map((npc, idx) => (
                  <div key={idx} className="flex items-start gap-2">
                    <span className="text-purple-300 text-sm">•</span>
                    <div>
                      <span className="text-white text-sm font-medium">
                        {npc.name}
                      </span>
                      {npc.role && (
                        <span className="text-gray-400 text-xs ml-2">
                          ({npc.role})
                        </span>
                      )}
                    </div>
                  </div>
                ))}
                {npcs.length > 4 && (
                  <p className="text-gray-500 text-xs italic ml-2">
                    ...and {npcs.length - 4} more
                  </p>
                )}
              </div>
            </div>
          )}

          {/* Factions */}
          {factions.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Shield className="text-red-400" size={16} />
                <h4 className="text-red-400 font-semibold text-sm">
                  Factions in Play
                </h4>
              </div>
              <div className="space-y-2 ml-6" data-testid="world-factions">
                {factions.slice(0, 4).map((faction, idx) => (
                  <div key={idx} className="text-sm">
                    <div className="text-white font-medium">{faction.name}</div>
                    {(faction.domain || faction.stance) && (
                      <div className="text-gray-400 text-xs mt-0.5">
                        {faction.domain && <span>{faction.domain}</span>}
                        {faction.domain && faction.stance && <span className="text-gray-600"> · </span>}
                        {faction.stance && <span className="italic">{faction.stance}</span>}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Recent Events */}
          {recentEvents.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Scroll className="text-cyan-400" size={16} />
                <h4 className="text-cyan-400 font-semibold text-sm">
                  Recent History
                </h4>
              </div>
              <div className="space-y-2 ml-6" data-testid="world-recent-events">
                {recentEvents.slice(0, 3).map((event, idx) => (
                  <div key={idx} className="text-sm">
                    <div className="text-white font-medium">{event.title}</div>
                    {event.summary && (
                      <div className="text-gray-400 text-xs mt-0.5 leading-relaxed">{event.summary}</div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default WorldInfoPanel;
